/* From Uiverse.io by adamgiebl - Tags: flashy, pink, gradient, button */
.__UIV_SCOPE__ button {
  position: relative;
  font-family: inherit;
  font-size: 18px;
  border-radius: 40em;
  width: 8em;
  height: 3em;
  z-index: 1;
  color: white;
  overflow: hidden;
  border: none;
}

.__UIV_SCOPE__ button .text {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  line-height: 3em;
  border-radius: 40em;
  border: none;
  background: linear-gradient(rgba(255, 255, 255, 0.473), rgba(150, 150, 150, 0.25));
  z-index: 1;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.__UIV_SCOPE__ button .blob {
  position: absolute;
  z-index: -1;
  border-radius: 5em;
  width: 5em;
  height: 3em;
  transition: transform .3s ease-in-out, background .3s ease-in-out;
}

.__UIV_SCOPE__ button .blob:nth-child(2) {
  left: 0em;
  top: 0;
  background: #ff930f;
}

.__UIV_SCOPE__ button .blob:nth-child(3) {
  left: 1.8em;
  top: 0;
  z-index: -1;
  background: #bf0fff;
}

.__UIV_SCOPE__ button .blob:nth-child(4) {
  left: 4em;
  top: -1em;
  background: #ff1b6b;
}

.__UIV_SCOPE__ button .blob:nth-child(5) {
  left: 4.3em;
  top: 1.6em;
  background: #0061ff;
}

.__UIV_SCOPE__ button:hover .blob:nth-child(2) {
  background: #0061ff;
}

.__UIV_SCOPE__ button:hover .blob:nth-child(3) {
  background: #ff1b6b;
}

.__UIV_SCOPE__ button:hover .blob:nth-child(4) {
  background: #bf0fff;
}

.__UIV_SCOPE__ button:hover .blob:nth-child(5) {
  background: #ff930f;
}

.__UIV_SCOPE__ button:hover .blob {
  transform: scale(1.3);
}

.__UIV_SCOPE__ button:active {
  border: 2px solid white;
}
